import java.util.*;

public class Main {

    static final int MOD = 1_000_000_007;

    static class ModInt {
        int val;

        ModInt(long v) {
            int tmp = (int)(v % MOD);
            if (tmp < 0) tmp += MOD;
            val = tmp;
        }

        ModInt(int v) {
            val = v % MOD;
            if (val < 0) val += MOD;
        }

        ModInt add(ModInt other) {
            int res = (long)this.val + other.val >= MOD ? (this.val + other.val) - MOD : this.val + other.val;
            return new ModInt(res);
        }

        ModInt subtract(ModInt other) {
            int res = this.val - other.val;
            if (res < 0) res += MOD;
            return new ModInt(res);
        }

        ModInt multiply(ModInt other) {
            long prod = (long)this.val * other.val;
            return new ModInt((int)(prod % MOD));
        }

        ModInt divide(ModInt other) {
            return this.multiply(other.inv());
        }

        ModInt inv() {
            int a = this.val;
            if (a == 0) return new ModInt(0);
            int g = MOD, r = a, x = 0, y = 1;
            while (r != 0) {
                int q = g / r;
                int newG = g % r;
                int newR = r;
                g = r;
                r = newG;
                int newX = x - q * y;
                x = y;
                y = newX;
            }
            int inv = x < 0 ? x + MOD : x;
            return new ModInt(inv);
        }

        // For convenience, to get the int value
        int getVal() { return val; }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof ModInt)) return false;
            ModInt modInt = (ModInt) o;
            return val == modInt.val;
        }

        @Override
        public int hashCode() {
            return val;
        }
    }

    static int modInverse(int a, int m) {
        int g = m, r = a, x = 0, y = 1;
        while (r != 0) {
            int q = g / r;
            g %= r;
            int tmp = g; g = r; r = tmp;
            x -= q * y;
            int tmp2 = x; x = y; y = tmp2;
        }
        return x < 0 ? x + m : x;
    }

    static int modMul(int a, int b) {
        return (int)((long)a * b % MOD);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        ModInt[][] prob = new ModInt[N][N];
        ModInt inv100 = new ModInt(100).inv();
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                int p = sc.nextInt();
                prob[i][j] = new ModInt(p).multiply(inv100);
            }
        }

        int maxMask = 1 << N;
        List<List<Integer>> masksWithCount = new ArrayList<>(N + 1);
        for (int i = 0; i <= N; i++) {
            masksWithCount.add(new ArrayList<>());
        }
        int[] lookup = new int[maxMask];
        Arrays.fill(lookup, -1);
        for (int mask = 0; mask < maxMask; mask++) {
            int cnt = Integer.bitCount(mask);
            lookup[mask] = masksWithCount.get(cnt).size();
            masksWithCount.get(cnt).add(mask);
        }

        HashMap<Long, ModInt> possibleMasks = new HashMap<>();
        possibleMasks.put(1L << lookup[0], new ModInt(1));

        for (int left = 0; left < N; left++) {
            HashMap<Long, ModInt> newPossibleMasks = new HashMap<>();
            ModInt[] products = new ModInt[maxMask];
            for (int cur = 0; cur < maxMask; cur++) {
                ModInt prod = new ModInt(1);
                for (int right = 0; right < N; right++) {
                    if ((cur >> right & 1) == 1) {
                        prod = prod.multiply(prob[left][right]);
                    } else {
                        prod = prod.multiply(new ModInt(1).subtract(prob[left][right]));
                    }
                }
                products[cur] = prod;
            }

            for (Map.Entry<Long, ModInt> entry : possibleMasks.entrySet()) {
                long possible = entry.getKey();
                ModInt probVal = entry.getValue();

                long[] newBits = new long[N];
                for (int mask : masksWithCount.get(left)) {
                    if ((possible >> lookup[mask] & 1) == 1) {
                        for (int i = 0; i < N; i++) {
                            if ((mask >> i & 1) == 0) {
                                newBits[i] |= 1L << lookup[mask | (1 << i)];
                            }
                        }
                    }
                }

                long[] newPossible = new long[maxMask];
                newPossible[0] = 0;
                for (int cur = 1; cur < maxMask; cur++) {
                    int lowBit = cur & -cur;
                    int idx = Integer.numberOfTrailingZeros(cur);
                    newPossible[cur] = newPossible[cur ^ lowBit] | newBits[idx];
                    long key = newPossible[cur];
                    ModInt addVal = probVal.multiply(products[cur]);
                    newPossibleMasks.merge(key, addVal, (a, b) -> a.add(b));
                }
            }
            possibleMasks = newPossibleMasks;
        }

        int fullMask = (1 << N) - 1;
        int fullIdx = lookup[fullMask];
        ModInt answer = new ModInt(0);
        for (Map.Entry<Long, ModInt> entry : possibleMasks.entrySet()) {
            if ((entry.getKey() >> fullIdx & 1) == 1) {
                answer = answer.add(entry.getValue());
            }
        }
        System.out.println(answer.getVal());
    }
}
